"use client";

import { useEffect, useId, useRef, useState, type ComponentProps } from "react";

import { IconAlertCircle, IconInfo, IconSmartphone } from "@rhs-ui/icons";
import { Label } from "@rhs-ui/primitives/label";
import { countSms, DEFAULT_LABELS, describeCharacter, hasPlainForm, plainText, type SmsCount, type SmsLabels } from "@rhs-ui/primitives/sms-message-field/sms";
import { Textarea } from "@rhs-ui/primitives/textarea";
import { cn } from "@/lib/utils";

export type { SmsCount, SmsEncoding, SmsLabels } from "@rhs-ui/primitives/sms-message-field/sms";

export interface SmsMessageFieldProps extends Omit<ComponentProps<"textarea">, "value" | "defaultValue" | "onChange" | "children" | "rows" | "maxLength"> {
  /** The message, when you control it. */
  value?: string;
  /** The message to start with, when you do not control it. */
  defaultValue?: string;
  /** Called with the message and what it will cost as text messages, on every change. */
  onValueChange?: (value: string, count: SmsCount) => void;
  /** The most messages one text may take. Past it the counter and the bar turn to the error colour and the field is `aria-invalid`; nothing is cut off. */
  maxSegments?: number;
  /** The name the messages arrive from, shown beside the label: "Northwind". It is not part of the count. */
  senderLabel?: string;
  /** The name of the field, shown above it. */
  label?: string;
  /** Keep `label` for assistive technology only. */
  hideLabel?: boolean;
  /** How many lines of text show before the field grows or scrolls. Default 4. */
  rows?: number;
  /** The field's name for a plain form submit: the message as it is. */
  name?: string;
  /** The words the field says, for another language or your own voice. */
  labels?: Partial<SmsLabels>;
}

/** At most this many bars show; a message longer than that fills them all. */
const MAX_BARS = 8;

/** Variation selectors and the joiner inside an emoji sequence: part of the emoji, not something to name. */
const INVISIBLE = new Set([0xfe0e, 0xfe0f, 0x200d]);

/** A list in words: "a", "a and b", "a, b and c". */
function inWords(items: readonly string[]): string {
  return items.length < 2 ? (items[0] ?? "") : `${items.slice(0, -1).join(", ")} and ${items[items.length - 1]}`;
}

/**
 * A text message box that counts messages, not characters. One message holds
 * 160 characters in the standard alphabet and only 70 once a single character
 * is outside it, and a text that runs longer is split into parts of 153 or 67.
 * The counter reads "2 messages, 214 characters, Unicode" next to a bar that
 * fills one segment per message, and a line names the characters that forced
 * Unicode (an emoji, a curly apostrophe) so they can be taken out, with one
 * button that swaps the look-alikes for plain ones. Characters of the extension
 * table (the euro sign, brackets, braces and a few more) count double, and in
 * Unicode so does an emoji, which the line says as soon as one is in the text. The count is announced
 * politely only when the number of messages changes. The helpers `countSms` and
 * `plainText` live in `sms-message-field/sms`.
 */
export function SmsMessageField({
  value,
  defaultValue = "",
  onValueChange,
  maxSegments,
  senderLabel,
  label,
  hideLabel = false,
  rows = 4,
  name,
  labels: labelOverrides,
  id,
  disabled,
  readOnly,
  className,
  "aria-label": ariaLabel,
  "aria-labelledby": labelledBy,
  "aria-describedby": describedBy,
  ...props
}: SmsMessageFieldProps) {
  const uid = useId();
  const areaId = id ?? `${uid}-area`;
  const counterId = `${uid}-counter`;
  const noteId = `${uid}-note`;
  const labels: SmsLabels = { ...DEFAULT_LABELS, ...labelOverrides };
  const [own, setOwn] = useState(defaultValue);
  const [said, setSaid] = useState("");
  const text = value ?? own;
  const area = useRef<HTMLTextAreaElement | null>(null);
  const count = countSms(text);
  const before = useRef(count.segments);

  // The number of messages is announced when it changes, not on every key.
  useEffect(() => {
    if (before.current === count.segments) return;
    before.current = count.segments;
    setSaid(count.segments === 0 ? "" : labels.announce(count.segments, count.encoding));
  }, [count.segments, count.encoding, labels]);

  useEffect(() => {
    if (!said) return;
    const timer = window.setTimeout(() => setSaid(""), 4000);
    return () => window.clearTimeout(timer);
  }, [said]);

  function write(next: string) {
    if (value === undefined) setOwn(next);
    onValueChange?.(next, countSms(next));
  }

  function replace() {
    const node = area.current;
    const next = plainText(text);
    if (!node || next === text) return;
    node.focus();
    node.select();
    // insertText is an edit the browser knows about, so Ctrl or Cmd+Z brings the curly quotes back.
    let done = false;
    try {
      done = document.execCommand("insertText", false, next);
    } catch {
      done = false;
    }
    if (!done) write(next);
    setSaid(labels.replaced);
  }

  const over = maxSegments !== undefined && count.segments > maxSegments;
  const forcing = count.forcing.filter((character) => !INVISIBLE.has(character.codePointAt(0) ?? 0));
  const names = forcing.slice(0, 4).map((character) => (/\s/.test(character) ? describeCharacter(character) : `${character} (${describeCharacter(character)})`));
  if (forcing.length > names.length) names.push(`${forcing.length - names.length} more`);
  const standard = 160;
  const bars = Math.min(MAX_BARS, Math.max(1, maxSegments ?? Math.max(3, count.segments)));
  const hasPlain = forcing.some((character) => hasPlainForm(character));
  const doubled = count.doubled.map((character) => (character === "\f" ? "form feed" : character));
  // In Unicode an emoji takes two places while the counter counts it once, so the limit and the count only add up with that said.
  const wide = count.encoding === "unicode" && count.units > count.characters;
  const note =
    count.encoding === "unicode" ? `${labels.forcedBy(inWords(names), 70, standard)}${wide ? ` ${labels.emojiDoubled}` : ""}` : doubled.length > 0 ? labels.doubled(doubled.join(" ")) : null;
  /** How full the bar of one message is, from 0 to 1. */
  const fill = (index: number) => Math.min(1, (count.parts[index] ?? 0) / count.perSegment);
  const named = label !== undefined || id !== undefined || ariaLabel !== undefined || labelledBy !== undefined;

  return (
    <div data-slot="sms-message-field" className={cn("grid w-full min-w-0 grid-cols-1 gap-2", className)}>
      {label || senderLabel ? (
        <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
          {label ? (
            <Label htmlFor={areaId} className={cn(hideLabel && "sr-only")}>
              {label}
            </Label>
          ) : (
            <span />
          )}
          {senderLabel ? (
            <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
              <IconSmartphone aria-hidden="true" className="size-3.5" />
              <span>
                From <span className="font-medium text-foreground">{senderLabel}</span>
              </span>
            </span>
          ) : null}
        </div>
      ) : null}
      <Textarea
        {...props}
        ref={area}
        id={areaId}
        name={name}
        rows={rows}
        readOnly={readOnly}
        disabled={disabled}
        value={text}
        aria-label={named ? ariaLabel : labels.name}
        aria-labelledby={labelledBy}
        aria-invalid={over ? true : undefined}
        aria-describedby={[describedBy, counterId, note ? noteId : ""].filter(Boolean).join(" ")}
        onChange={(event) => {
          setSaid("");
          write(event.target.value);
        }}
      />
      <div aria-hidden="true" className="flex gap-1">
        {Array.from({ length: bars }, (_, index) => (
          <span key={index} className="h-1.5 min-w-0 flex-1 overflow-hidden rounded-full bg-muted">
            <span
              className={cn("block h-full rounded-full transition-[width] duration-150 motion-reduce:transition-none", over ? "bg-destructive" : "bg-foreground")}
              style={{ width: `${Math.round(fill(index) * 100)}%` }}
            />
          </span>
        ))}
      </div>
      <p id={counterId} className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5 text-xs text-muted-foreground tabular-nums">
        <span>
          <span className={cn("font-medium", over ? "text-destructive" : "text-foreground")}>{labels.messages(count.segments)}</span>
          {", "}
          {labels.characters(count.characters)}
          {", "}
          <span className={cn(count.encoding === "unicode" && "font-medium text-foreground")}>{count.encoding === "unicode" ? labels.unicode : labels.gsm}</span>
        </span>
        {count.segments > 0 ? <span>{labels.left(count.left, count.segments)}</span> : null}
      </p>
      {note || over ? (
        <div id={noteId} className="grid gap-1.5 text-xs">
          {over && maxSegments !== undefined ? (
            <p className="flex items-start gap-1.5 text-destructive">
              <IconAlertCircle aria-hidden="true" className="mt-px size-3.5 shrink-0" />
              {labels.over(count.segments, maxSegments)}
            </p>
          ) : null}
          {note ? (
            <p className="flex items-start gap-1.5 text-muted-foreground">
              <IconInfo aria-hidden="true" className="mt-px size-3.5 shrink-0" />
              <span className="min-w-0 [overflow-wrap:anywhere]">
                {note}
                {hasPlain && !readOnly && !disabled ? (
                  <>
                    {" "}
                    <button
                      type="button"
                      onClick={replace}
                      className="-mx-0.5 rounded-sm px-0.5 font-medium text-foreground underline decoration-foreground/30 underline-offset-4 outline-none hover:decoration-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40"
                    >
                      {labels.usePlain}
                    </button>
                  </>
                ) : null}
              </span>
            </p>
          ) : null}
        </div>
      ) : null}
      <span role="status" className="sr-only">
        {said}
      </span>
    </div>
  );
}

/**
 * The characters of the standard SMS alphabet (GSM 03.38), each worth one
 * place in a message. Any character outside it, and outside the extension
 * table below, makes the whole message Unicode.
 */
export const GSM_BASIC = "@\u00a3$\u00a5\u00e8\u00e9\u00f9\u00ec\u00f2\u00c7\n\u00d8\u00f8\r\u00c5\u00e5\u0394_\u03a6\u0393\u039b\u03a9\u03a0\u03a8\u03a3\u0398\u039e\u00c6\u00e6\u00df\u00c9 !\"#\u00a4%&'()*+,-./0123456789:;<=>?\u00a1ABCDEFGHIJKLMNOPQRSTUVWXYZ\u00c4\u00d6\u00d1\u00dc\u00a7\u00bfabcdefghijklmnopqrstuvwxyz\u00e4\u00f6\u00f1\u00fc\u00e0";

/** The extension table: still the standard alphabet, but each character takes two places. */
export const GSM_EXTENSION = "^{}\\[~]|\u20ac\f";

const BASIC = new Set([...GSM_BASIC]);
const EXTENSION = new Set([...GSM_EXTENSION]);

export type SmsEncoding = "gsm" | "unicode";

/** What a text will cost as text messages. */
export interface SmsCount {
  /** The alphabet the text needs: `gsm` for the standard one, `unicode` as soon as one character is outside it. */
  encoding: SmsEncoding;
  /** How many messages the text takes. 0 for no text. */
  segments: number;
  /** The characters, counted by code point: most emoji are one, an emoji with a skin tone or a joiner is more. The messages are worked out from `units`, not from this. */
  characters: number;
  /** The places used: an extension character or an emoji takes two. */
  units: number;
  /** What one message of this text holds: 160 or 153 (when split) in GSM, 70 or 67 in Unicode. */
  perSegment: number;
  /** The places used in each message. */
  parts: number[];
  /** The places left in the last message. */
  left: number;
  /** The characters that forced Unicode, each once, in the order they appear. */
  forcing: string[];
  /** The extension characters in the text, each once. Empty in Unicode, where they cost nothing extra. */
  doubled: string[];
}

/** True for a character of the standard alphabet or its extension table. */
export function isGsm(character: string): boolean {
  return BASIC.has(character) || EXTENSION.has(character);
}

/**
 * Works out how many text messages a text takes. One message holds 160 places
 * in the standard alphabet and 70 once any character needs Unicode; a text
 * that is split holds 153 and 67 per part, because each part carries a header.
 * Characters from the extension table (the euro sign, brackets, braces and a few more) and emoji take
 * two places, and a character is never split over two parts.
 */
export function countSms(text: string): SmsCount {
  const characters = [...text];
  const forcing: string[] = [];
  for (const character of characters) if (!isGsm(character) && !forcing.includes(character)) forcing.push(character);
  const encoding: SmsEncoding = forcing.length === 0 ? "gsm" : "unicode";
  const widths = characters.map((character) => (encoding === "unicode" ? character.length : BASIC.has(character) ? 1 : 2));
  const units = widths.reduce((sum, width) => sum + width, 0);
  const single = encoding === "gsm" ? 160 : 70;
  const split = encoding === "gsm" ? 153 : 67;
  const doubled = encoding === "gsm" ? [...new Set(characters.filter((character) => EXTENSION.has(character)))] : [];
  const base = { encoding, characters: characters.length, units, forcing, doubled };
  if (characters.length === 0) return { ...base, segments: 0, perSegment: single, parts: [], left: single };
  if (units <= single) return { ...base, segments: 1, perSegment: single, parts: [units], left: single - units };
  const parts = [0];
  for (const width of widths) {
    if ((parts[parts.length - 1] ?? 0) + width > split) parts.push(0);
    parts[parts.length - 1] = (parts[parts.length - 1] ?? 0) + width;
  }
  return { ...base, segments: parts.length, perSegment: split, parts, left: split - (parts[parts.length - 1] ?? 0) };
}

/** What the usual look-alikes turn into: curly quotes, dashes, the ellipsis, a non-breaking space. Built from code points, so the source stays free of the characters themselves. */
const PLAIN = new Map<string, string>(
  (
    [
      [0x2018, "'"],
      [0x2019, "'"],
      [0x201a, "'"],
      [0x00b4, "'"],
      [0x201c, '"'],
      [0x201d, '"'],
      [0x201e, '"'],
      [0x2013, "-"],
      [0x2014, "-"],
      [0x2212, "-"],
      [0x2026, "..."],
      [0x2022, "*"],
      [0x00a0, " "],
      [0x202f, " "],
      [0x2009, " "],
    ] as const
  ).map(([code, plain]) => [String.fromCharCode(code), plain]),
);

/** True when `plainText` has a standard replacement for the character. */
export function hasPlainForm(character: string): boolean {
  return PLAIN.has(character);
}

/** The text with the look-alikes that force Unicode swapped for the standard characters. Letters and emoji are left alone: only the writer knows what to do with those. */
export function plainText(text: string): string {
  return [...text].map((character) => PLAIN.get(character) ?? character).join("");
}

/** A short name for a character that forced Unicode, so a person can find it: "emoji", "curly apostrophe", "letter". */
export function describeCharacter(character: string): string {
  const code = character.codePointAt(0) ?? 0;
  if (code === 0x2018 || code === 0x2019 || code === 0x201a) return "curly apostrophe";
  if (code === 0x201c || code === 0x201d || code === 0x201e) return "curly quote";
  if (code === 0x2013) return "en dash";
  if (code === 0x2014) return "em dash";
  if (code === 0x2026) return "ellipsis";
  if (code === 0x2022) return "bullet";
  if (code === 0x00a0 || code === 0x202f || code === 0x2009) return "special space";
  if (/\p{Extended_Pictographic}/u.test(character)) return "emoji";
  if (/\p{L}/u.test(character)) return "letter";
  return "symbol";
}

/** The words the field says, for another language or your own voice. Each can be replaced. */
export interface SmsLabels {
  /** "2 messages". */
  messages: (count: number) => string;
  /** "214 characters". */
  characters: (count: number) => string;
  /** The standard alphabet, as the counter names it. */
  gsm: string;
  /** The other alphabet, as the counter names it. */
  unicode: string;
  /** What is left in the last message: "28 left in this message", or "62 left before message 4" once the text is split. */
  left: (count: number, segments: number) => string;
  /** The line that names what forced Unicode: `what` is the characters with their names, `single` and `standard` are the two limits. */
  forcedBy: (what: string, single: number, standard: number) => string;
  /** The line that names the characters that take two places. */
  doubled: (what: string) => string;
  /** Added to the Unicode line while the text holds an emoji, which takes two places of the message although the counter counts it once. */
  emojiDoubled: string;
  /** The line when there are more messages than `maxSegments`. */
  over: (segments: number, max: number) => string;
  /** The button that swaps curly quotes and dashes for plain ones. */
  usePlain: string;
  /** What a screen reader hears after it. */
  replaced: string;
  /** What a screen reader hears when the number of messages changes. */
  announce: (segments: number, encoding: SmsEncoding) => string;
  /** The name of the field when it has no label. */
  name: string;
}

const plural = (count: number, one: string, other: string) => (count === 1 ? one : other);

export const DEFAULT_LABELS: SmsLabels = {
  messages: (count) => `${count} ${plural(count, "message", "messages")}`,
  characters: (count) => `${count} ${plural(count, "character", "characters")}`,
  gsm: "GSM",
  unicode: "Unicode",
  left: (count, segments) => (segments <= 1 ? `${count} left in this message` : `${count} left before message ${segments + 1}`),
  forcedBy: (what, single, standard) => `Unicode because of ${what}. A message holds ${single} characters instead of ${standard}.`,
  doubled: (what) => `${what} count as two characters each.`,
  emojiDoubled: "Emoji count as two characters each.",
  over: (segments, max) => `That is ${segments} messages and the limit is ${max}.`,
  usePlain: "Use plain characters",
  replaced: "Replaced with plain characters.",
  announce: (segments, encoding) => `${segments} ${plural(segments, "message", "messages")}${encoding === "unicode" ? ", Unicode" : ""}`,
  name: "Message",
};
